1053	        attention::attention_forward<ActT, 32, /*kCausal=*/true>(
1054	            q_buf, k_buf, v_buf,
1055	            sl.attn_out_perhead, sl.softmax_lse,
1056	            B, H, S, scale, stream);
1057	
1058	        // Reshape attention output [B, H, S, d] -> [B, S, D]
