1060	            sl.attn_out_perhead, sl.attn_out, B, S, H, d_head);
1061	        SG_LAUNCH_CHECK(stream);
1062	
1063	        // Output projection: attn_proj = attn_out @ out_W^T  (out_W [D,D]).
1064	#ifdef WITH_CUTLASS
1065	        bool outp_done = false;
1066	        if constexpr (cutlass_gemm_any_tc<WeightT>::value) {
1067	            outp_done = (decoder_linear_gemm_tc<WeightT, cutlass::layout::ColumnMajor>(
1068	                B*S, D, D,
1069	                (const WeightT*)sl.attn_out, lw.out_W,
1070	                (WeightT*)sl.attn_proj, stream) == cudaSuccess);
1071	        }
1072	        if (!outp_done)
1073	#endif
1074	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_T,
1075	            B*S, D, D, 1.0f, 0.0f,
1076	            (const WeightT*)sl.attn_out, D, lw.out_W, D,
1077	            (WeightT*)sl.attn_proj, D, stream);
1078	        bias_add_kernel<ActT, WeightT><<<B*S, 128, 0, stream>>>(
1079	            sl.attn_proj, lw.out_b, B*S, D);
1080	        SG_LAUNCH_CHECK(stream);
1081	
1082	        // n1: x = LN(qkv_in + attn_proj) [post-norm]
1083	        residual_layernorm_kernel<ActT, WeightT>
1084	            <<<B*S, 128, D*sizeof(float), stream>>>(
1085	                sl.qkv_in, sl.attn_proj, lw.n1_g, lw.n1_b,
1086	                sl.n1_in, sl.layer1_out, B*S, D, eps);
1087	        SG_LAUNCH_CHECK(stream);
1088	
1089	        // FFN up: ffn_pre = layer1_out @ ff1_W^T  (ff1_W [FH,D]).
1090	#ifdef WITH_CUTLASS
1091	        bool ff1_done = false;
1092	        if constexpr (cutlass_gemm_any_tc<WeightT>::value) {
1093	            ff1_done = (decoder_linear_gemm_tc<WeightT, cutlass::layout::ColumnMajor>(
1094	                B*S, FH, D,
1095	                (const WeightT*)sl.layer1_out, lw.ff1_W,
1096	                (WeightT*)sl.ffn_pre, stream) == cudaSuccess);
1097	        }
1098	        if (!ff1_done)
1099	#endif
1100	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_T,
1101	            B*S, FH, D, 1.0f, 0.0f,
1102	            (const WeightT*)sl.layer1_out, D, lw.ff1_W, D,
1103	            (WeightT*)sl.ffn_pre, FH, stream);
1104	        bias_add_kernel<ActT, WeightT><<<B*S, 256, 0, stream>>>(
1105	            sl.ffn_pre, lw.ff1_b, B*S, FH);
1106	        SG_LAUNCH_CHECK(stream);
1107	
1108	        // GELU
1109	        {
1110	            size_t n = (size_t)B*S*FH;
1111	            int block = 256, grid = (int)((n + block - 1) / block);
1112	            gelu_fwd_kernel<ActT><<<grid, block, 0, stream>>>(
1113	                sl.ffn_pre, sl.ffn_post, n);
1114	            SG_LAUNCH_CHECK(stream);
1115	        }
1116	
1117	        // FFN down: ffn_out = ffn_post @ ff2_W^T  (ff2_W [D,FH]).
1118	#ifdef WITH_CUTLASS
1119	        bool ff2_done = false;
1120	        if constexpr (cutlass_gemm_any_tc<WeightT>::value) {
1121	            ff2_done = (decoder_linear_gemm_tc<WeightT, cutlass::layout::ColumnMajor>(
1122	                B*S, D, FH,
1123	                (const WeightT*)sl.ffn_post, lw.ff2_W,
1124	                (WeightT*)sl.ffn_out, stream) == cudaSuccess);
1125	        }
1126	        if (!ff2_done)
1127	#endif
1128	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_T,
1129	            B*S, D, FH, 1.0f, 0.0f,
1130	            (const WeightT*)sl.ffn_post, FH, lw.ff2_W, FH,
1131	            (WeightT*)sl.ffn_out, D, stream);
1132	        bias_add_kernel<ActT, WeightT><<<B*S, 128, 0, stream>>>(
1133	            sl.ffn_out, lw.ff2_b, B*S, D);
1134	        SG_LAUNCH_CHECK(stream);
1135	
1136	        // n2: layer_out = LN(layer1_out + ffn_out) [post-norm]
1137	        residual_layernorm_kernel<ActT, WeightT>
1138	            <<<B*S, 128, D*sizeof(float), stream>>>(
1139	                sl.layer1_out, sl.ffn_out, lw.n2_g, lw.n2_b,
1140	                sl.n2_in, sl.layer_out, B*S, D, eps);
1141	        SG_LAUNCH_CHECK(stream);
1142	
1143	        layer_input = sl.layer_out;
1144	    }
1145	
1146	    // Final LayerNorm
1147	    ActT* final_norm_out = activations + L.input_ids_saved + L.embed_out + (size_t)n_layers * L.per_layer_total;
1148	    layernorm_kernel<ActT, WeightT>
1149	        <<<B*S, 128, D*sizeof(float), stream>>>(
1150	            layer_input, final_g, final_b, final_norm_out, B*S, D, eps);
1151	    SG_LAUNCH_CHECK(stream);
1152	
1153	    // Vocab head (full): logits[B*S, V] = norm @ vocab_W^T + b  (vocab_W [V,D]).
1154	    ActT* logits_full = final_norm_out + L.final_norm_out;
1155	#ifdef WITH_CUTLASS
1156	    bool vocab_done = false;
1157	    if constexpr (cutlass_gemm_any_tc<WeightT>::value) {
1158	        vocab_done = (decoder_linear_gemm_tc<WeightT, cutlass::layout::ColumnMajor>(
1159	            B*S, V, D,
1160	            (const WeightT*)final_norm_out, vocab_W,
1161	            (WeightT*)logits_full, stream) == cudaSuccess);
1162	    }
1163	    if (!vocab_done)
1164	#endif
1165	    cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_T,
1166	        B*S, V, D, 1.0f, 0.0f,
1167	        (const WeightT*)final_norm_out, D, vocab_W, D,
1168	        (WeightT*)logits_full, V, stream);
1169	    bias_add_kernel<ActT, WeightT><<<B*S, 128, 0, stream>>>(
1170	        logits_full, vocab_b, B*S, V);
1171	    SG_LAUNCH_CHECK(stream);
1172	
1173	    // Last-token output [B, V]
1174	    last_token_kernel<ActT><<<B, 128, 0, stream>>>(
