1182	// ─── Backward orchestration ──────────────────────────────────────────
1183	//
1184	// Implementation strategy: every weight-grad GEMM is computed BEFORE the
1185	// activation that it consumes is overwritten. Where we need to overwrite
1186	// a saved activation (to run a backward GEMM into it), we issue the
1187	// weight-grad GEMM first.
1188	//
1189	// We use the activation buffer as scratch by reusing slots that are no
1190	// longer needed. Specifically:
1191	//   * grad_layer_out (input grad of n2): held in workspace W1
1192	//   * grad_ffn_out  (= grad_n2_in): held in W1 (it's the output of LN bwd)
1193	//   * grad_ffn_post: held in W2 (activation grad of GEMM2)
1194	//   * grad_ffn_pre:  W2 (after GELU bwd)
1195	//   * grad_layer1_out (residual + GEMM1.A grad): W1 (after add)
1196	//   * grad_n1_in:    W1 (output of LN bwd)
1197	//   * grad_attn_proj: W1
1198	//   * grad_attn_out: W2
1199	//   * grad_attn_perhead: W3 (we need a third buffer for QKV layout)
1200	//   * grad_q/grad_k/grad_v: W1, W2, W3 (overwriting attn_in_qkv slabs)
1201	//   * grad_qkv_out: W4 (or reuse qkv_out — we overwrite it last)
1202	//   * grad_qkv_in: W1 (final output for layer)
1203	//
1204	// We allocate W1/W2/W3 by overwriting saved layer activations in the
1205	// reverse order they're consumed. The key invariants:
1206	//   - sl.qkv_in must be preserved until grad_qkv_W is computed.
1207	//   - sl.layer1_out must be preserved until grad_ff1_W is computed.
1208	//   - sl.ffn_post must be preserved until grad_ff2_W is computed.
1209	//   - sl.attn_out must be preserved until grad_out_W is computed.
1210	//   - sl.attn_in_qkv (q,k,v) must be preserved until attention_backward.
1211	//   - sl.qkv_out is no longer needed once Q,K,V are split (we rebuild for
1212	//     forward consistency, but for backward we overwrite as grad_qkv_out).
1213	//
1214	template <typename ActT, typename WeightT>
1215	cudaError_t backward(
1216	    const ActT* grad_output,
1217	    const ActT* activations_saved,
1218	    const WeightT* weights,
1219	    ActT* grad_input,
1220	    WeightT* grad_weights,
1221	    int batch, int seq_len, int d_model, int n_heads, int d_head,
1222	    int n_layers, int vocab_size, int ffn_expansion,
1223	    cudaStream_t stream
1224	) {
1225	    const int B = batch, S = seq_len, D = d_model, H = n_heads, V = vocab_size;
1226	    const int FH = ffn_expansion * D;
1227	    const float scale = 1.0f / sqrtf((float)d_head);
1228	    const float eps = 1e-5f;
1229	    const size_t per_layer_w = per_layer_weight_count(D, FH);
1230	    auto L = compute_layout<ActT>(B, S, D, H, V, ffn_expansion);
1231	
1232	    const WeightT* wp = weights;
1233	    const WeightT* tok_embed = wp; wp += (size_t)V * D;
1234	    const WeightT* pos_embed = wp; wp += (size_t)S * D;
1235	    const WeightT* layers_w = wp; wp += (size_t)n_layers * per_layer_w;
1236	    const WeightT* final_g = wp; wp += D;
1237	    /* final_b */ wp += D;
1238	    const WeightT* vocab_W = wp; wp += (size_t)V * D;
1239	    /* vocab_b */ wp += V;
1240	    (void)tok_embed; (void)pos_embed;
1241	
1242	    WeightT* gwp = grad_weights;
1243	    WeightT* g_tok_embed = gwp; gwp += (size_t)V * D;
1244	    WeightT* g_pos_embed = gwp; gwp += (size_t)S * D;
1245	    WeightT* g_layers = gwp; gwp += (size_t)n_layers * per_layer_w;
1246	    WeightT* g_final_g = gwp; gwp += D;
1247	    WeightT* g_final_b = gwp; gwp += D;
1248	    WeightT* g_vocab_W = gwp; gwp += (size_t)V * D;
1249	    WeightT* g_vocab_b = gwp; gwp += V;
1250	
1251	    // Reuse the cached, per-stream cuBLAS handle (see forward()'s note); avoids
1252	    // a cublasCreate/Destroy (handle+workspace alloc/free, a sync point) on
1253	    // every backward call. (mamba3_sm90.cuh:533.)
1254	    auto cublas = at::cuda::getCurrentCUDABlasHandle();
1255	    cublasSetStream(cublas, stream);
1256	
1257	    ActT* act_base = const_cast<ActT*>(activations_saved);
1258	    const ActT* input_ids_saved = act_base;
1259	    ActT* final_norm_out = act_base + L.input_ids_saved + L.embed_out + (size_t)n_layers * L.per_layer_total;
1260	    ActT* logits_full = final_norm_out + L.final_norm_out;
1261	
1262	    // 1. Scatter grad_output into grad_logits_full (overwrites logits_full)
1263	    last_token_scatter_kernel<ActT><<<B*S, 128, 0, stream>>>(
1264	        grad_output, logits_full, B, S, V);
1265	    SG_LAUNCH_CHECK(stream);
1266	
1267	    // 2. Vocab head bwd. Compute weight grad FIRST (needs saved final_norm_out).
1268	    // grad_vocab_W [V, D] += grad_logits^T [V, B*S] * final_norm_out [B*S, D]
1269	    cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_T, CUBLAS_OP_N,
1270	        V, D, B*S, 1.0f, 1.0f,
1271	        (const WeightT*)logits_full, V,
1272	        (const WeightT*)final_norm_out, D,
1273	        g_vocab_W, D, stream);
1274	    // grad_vocab_b
1275	    bias_bwd_kernel<ActT, WeightT><<<(V+255)/256, 256, 0, stream>>>(
1276	        logits_full, g_vocab_b, B*S, V);
1277	    SG_LAUNCH_CHECK(stream);
1278	    // grad_norm_out (= grad of input to vocab head) = grad_logits * vocab_W
1279	    // Overwrite final_norm_out — no longer needed.
1280	    cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_N,
1281	        B*S, D, V, 1.0f, 0.0f,
1282	        (const WeightT*)logits_full, V, vocab_W, D,
1283	        (WeightT*)final_norm_out, D, stream);
1284	
1285	    // 3. Final LayerNorm bwd. Input was last layer's layer_out.
1286	    auto sl_last = slice_layer<ActT>(act_base, L, n_layers - 1);
1287	    ActT* grad_stack_out = logits_full;  // reuse — sized [B*S*V] which is >> [B*S*D]
1288	    layernorm_bwd_kernel<ActT, WeightT>
1289	        <<<B*S, 128, D*sizeof(float), stream>>>(
1290	            sl_last.layer_out, final_norm_out, final_g,
1291	            grad_stack_out, g_final_g, g_final_b, B*S, D, eps);
1292	    SG_LAUNCH_CHECK(stream);
1293	
1294	    ActT* grad_y = grad_stack_out;  // grad w.r.t. last layer's output
1295	
1296	    // 4. Per-layer backward (reverse order)
1297	    for (int li = n_layers - 1; li >= 0; li--) {
1298	        auto sl = slice_layer<ActT>(act_base, L, li);
1299	        auto lw = slice_layer_weights<WeightT>(layers_w + (size_t)li * per_layer_w, D, FH);
1300	        auto gw = slice_layer_grads<WeightT>(g_layers + (size_t)li * per_layer_w, D, FH);
1301	
1302	        // ── n2 backward
1303	        // input was n2_in = layer1_out + ffn_out. Grad branches both.
1304	        // Write grad_n2_in into ffn_out (no longer needed).
1305	        layernorm_bwd_kernel<ActT, WeightT>
1306	            <<<B*S, 128, D*sizeof(float), stream>>>(
1307	                sl.n2_in, grad_y, lw.n2_g,
1308	                sl.ffn_out, gw.n2_g, gw.n2_b, B*S, D, eps);
1309	        SG_LAUNCH_CHECK(stream);
1310	        ActT* grad_n2_in = sl.ffn_out;     // alias (grad for both branches)
1311	
1312	        // ── FFN-down bwd: y = ffn_post * ff2_W^T + ff2_b
1313	        // First: weight grad uses saved ffn_post.
1314	        // grad_ff2_W [D, FH] += grad_y^T * ffn_post
1315	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_T, CUBLAS_OP_N,
1316	            D, FH, B*S, 1.0f, 1.0f,
1317	            (const WeightT*)grad_n2_in, D,
1318	            (const WeightT*)sl.ffn_post, FH,
1319	            gw.ff2_W, FH, stream);
1320	        bias_bwd_kernel<ActT, WeightT><<<(D+255)/256, 256, 0, stream>>>(
1321	            grad_n2_in, gw.ff2_b, B*S, D);
1322	        SG_LAUNCH_CHECK(stream);
1323	        // Then: activation grad. Overwrite ffn_post (no longer needed).
1324	        // grad_ffn_post = grad_n2_in * ff2_W
1325	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_N,
1326	            B*S, FH, D, 1.0f, 0.0f,
1327	            (const WeightT*)grad_n2_in, D, lw.ff2_W, FH,
1328	            (WeightT*)sl.ffn_post, FH, stream);
1329	        ActT* grad_ffn_post = sl.ffn_post;
1330	
1331	        // ── GELU bwd: in-place into ffn_pre (no longer needed after this)
1332	        {
1333	            size_t n = (size_t)B*S*FH;
1334	            int block = 256, grid = (int)((n + block - 1) / block);
1335	            gelu_bwd_kernel<ActT><<<grid, block, 0, stream>>>(
1336	                sl.ffn_pre, grad_ffn_post, sl.ffn_pre, n);
1337	            SG_LAUNCH_CHECK(stream);
1338	        }
1339	        ActT* grad_ffn_pre = sl.ffn_pre;
1340	
1341	        // ── FFN-up bwd: y = layer1_out * ff1_W^T + ff1_b
1342	        // Weight grad uses saved layer1_out.
1343	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_T, CUBLAS_OP_N,
1344	            FH, D, B*S, 1.0f, 1.0f,
1345	            (const WeightT*)grad_ffn_pre, FH,
1346	            (const WeightT*)sl.layer1_out, D,
1347	            gw.ff1_W, D, stream);
1348	        bias_bwd_kernel<ActT, WeightT><<<(FH+255)/256, 256, 0, stream>>>(
1349	            grad_ffn_pre, gw.ff1_b, B*S, FH);
1350	        SG_LAUNCH_CHECK(stream);
1351	        // Activation grad: grad_layer1_ff = grad_ffn_pre * ff1_W
1352	        // Overwrite layer1_out (no longer needed after weight grad).
1353	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_N,
1354	            B*S, D, FH, 1.0f, 0.0f,
1355	            (const WeightT*)grad_ffn_pre, FH, lw.ff1_W, D,
1356	            (WeightT*)sl.layer1_out, D, stream);
1357	        ActT* grad_layer1_ff = sl.layer1_out;
1358	
1359	        // grad_layer1_out total = grad_n2_in (residual branch) + grad_layer1_ff
1360	        {
1361	            size_t n = (size_t)B*S*D;
1362	            int block = 256, grid = (int)((n + block - 1) / block);
1363	            add_inplace_kernel<ActT><<<grid, block, 0, stream>>>(
1364	                grad_layer1_ff, grad_n2_in, n);
1365	            SG_LAUNCH_CHECK(stream);
1366	        }
1367	        ActT* grad_layer1_out = grad_layer1_ff;
1368	
1369	        // ── n1 bwd. Input was n1_in = qkv_in + attn_proj. Grad branches both.
1370	        // Write grad_n1_in into attn_proj (no longer needed).
1371	        layernorm_bwd_kernel<ActT, WeightT>
1372	            <<<B*S, 128, D*sizeof(float), stream>>>(
1373	                sl.n1_in, grad_layer1_out, lw.n1_g,
1374	                sl.attn_proj, gw.n1_g, gw.n1_b, B*S, D, eps);
1375	        SG_LAUNCH_CHECK(stream);
1376	        ActT* grad_n1_in = sl.attn_proj;
1377	
1378	        // ── out projection bwd: y = attn_out * out_W^T + out_b
1379	        // Weight grad uses saved attn_out.
1380	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_T, CUBLAS_OP_N,
1381	            D, D, B*S, 1.0f, 1.0f,
1382	            (const WeightT*)grad_n1_in, D,
1383	            (const WeightT*)sl.attn_out, D,
1384	            gw.out_W, D, stream);
1385	        bias_bwd_kernel<ActT, WeightT><<<(D+255)/256, 256, 0, stream>>>(
1386	            grad_n1_in, gw.out_b, B*S, D);
1387	        SG_LAUNCH_CHECK(stream);
1388	        // Activation grad. Overwrite attn_out.
1389	        cublas_gemm_rm<WeightT>(cublas, CUBLAS_OP_N, CUBLAS_OP_N,
1390	            B*S, D, D, 1.0f, 0.0f,
1391	            (const WeightT*)grad_n1_in, D, lw.out_W, D,
1392	            (WeightT*)sl.attn_out, D, stream);
1393	        ActT* grad_attn_out = sl.attn_out;
1394	
1395	        // Reshape [B, S, D] -> [B, H, S, d] for attention_backward
1396	        attn_out_inverse_reshape_kernel<ActT><<<B*S, 128, 0, stream>>>(
1397	            grad_attn_out, sl.attn_out_perhead, B, S, H, d_head);
1398	        SG_LAUNCH_CHECK(stream);
1399	        // After this, attn_out_perhead holds grad in [B,H,S,d] layout.
1400	
1401	        // ── Attention bwd
1402	        // q/k/v are stored in attn_in_qkv slabs. We allocate separate
1403	        // grad buffers (NOT aliased with q/k/v — the bwd kernel reads
1404	        // v multiple times).
1405	        ActT* q_buf = sl.attn_in_qkv;
1406	        ActT* k_buf = sl.attn_in_qkv + (size_t)B*S*D;
1407	        ActT* v_buf = sl.attn_in_qkv + (size_t)2*B*S*D;
1408	        // grad_q/k/v borrow ffn_pre/ffn_post (each [B,S,4D] >> [B,S,D]).
1409	        ActT* grad_q_buf = sl.ffn_pre;
1410	        ActT* grad_k_buf = sl.ffn_pre + (size_t)B*S*D;
1411	        ActT* grad_v_buf = sl.ffn_post;
1412	        // attention_backward consumes q,k,v + softmax_lse and produces grad_q/k/v.
1413	        // The 'out' arg is unused by the SMEM kernel — pass nullptr-equivalent
1414	        // (we pass q_buf for type-correctness; it's only touched by FA3 path).
1415	        attention::attention_backward<ActT, 32, /*kCausal=*/true>(
