516	    if (tok_id >= V) tok_id = V - 1;
517	    for (int d = tid; d < D; d += blockDim.x) {
518	        float t = to_float<W>(tok_embed[(size_t)tok_id * D + d]);
519	        float p = to_float<W>(pos_embed[(size_t)s * D + d]);
520	        out[(size_t)bs * D + d] = from_float<T>(t + p);
521	    }
